      mutate(!!new_name := map_missing(!!old_name)) %>%
      mutate(!!new_name := factor(!!new_name,
                                levels = c('-3', '-9', '-8', '-2', '-1', '1', '2', '3', '4', '5'),
                                labels = c(
                                  'Not asked at fieldwork stage',
                                  'Refused',
                                  'Don\'t know',
                                  'Schedule not applicable',
                                  'Not applicable',
                                  'Heterosexual / Straight',
                                  'Gay / Lesbian',
                                  'Bisexual',
                                  'Other',
                                  'Prefer not to say'
                                ))) %>%
      select(-any_of(old_name))
